static const unsigned int DRIVER_FLAG_16_BITS = 1;

static const unsigned int LOG_MODE_NONE = 0;
static const unsigned int LOG_MODE_TOP_LEVEL = 1;
static const unsigned int LOG_MODE_NESTED = 2;

static const int LOG_TIME_LENGTH = 24;

static const char LOG_FILE_MODE[] = "at";
static const char LOG_SEPARATOR[] = "-------------------------------------------------------------------------------";
static const char LOG_HEADER[] = "Miles Sound System usage script generated by MSS V9.3z";
static const char LOG_START_TIME[] = "Start time: %s";

static const char MATRIX_FILTER_ERROR[] = "Matrix filters require 16-bit PCM output format";
static const char OUTPUT_FILTER_ERROR[] = "Required output filter not found";

static int AIL_started = 0;

extern "C" AIL_LOG_CALLBACK AIL_configure_logging(const char* pFileName, AIL_LOG_CALLBACK pCallback, unsigned int uMode)
{
    time_t tNow;
    char szTime[LOG_TIME_LENGTH + 1];
    AIL_LOG_CALLBACK pPrevious;

    if (AIL_log_start_ms == 0)
    {
        AIL_log_start_ms = AIL_ms_count();
    }

    if (AIL_log_file != NULL)
    {
        fclose(AIL_log_file);
        AIL_log_file = NULL;
    }

    if (pFileName != NULL)
    {
        AIL_log_file = fopen(pFileName, LOG_FILE_MODE);
    }

    pPrevious = AIL_log_callback;
    AIL_log_callback = pCallback;

    switch (uMode)
    {
    case LOG_MODE_NONE:
        AIL_debug_nested = 0;
        AIL_debug_enabled = 0;
        break;
    case LOG_MODE_TOP_LEVEL:
        AIL_debug_enabled = 1;
        AIL_debug_nested = 0;
        break;
    case LOG_MODE_NESTED:
        AIL_debug_enabled = 1;
        AIL_debug_nested = 1;
        break;
    }

    if (uMode != LOG_MODE_NONE)
    {
        AIL_debug_log(LOG_SEPARATOR);
        AIL_debug_log(LOG_HEADER);
        time(&tNow);
        strcpy(szTime, asctime(localtime(&tNow)));
        szTime[LOG_TIME_LENGTH] = '\0';
        AIL_debug_log(LOG_START_TIME, szTime);
        AIL_debug_log(LOG_SEPARATOR);
    }

    return pPrevious;
}

extern "C" int AIL_startup()
{
    int iFirst = 0;

    AIL_debug_depth = AIL_debug_depth + 1;

    if (AIL_debug_enabled != 0 && (AIL_debug_depth == 1 || AIL_debug_nested != 0) && AIL_API_background() == 0)
    {
        AIL_debug_log("@AIL_startup()");
    }

    if (AIL_started == 0)
    {
        iFirst = 1;
        AIL_started = 1;
        AIL_API_startup();
    }

    if (AIL_debug_enabled != 0 && (AIL_debug_depth == 1 || AIL_debug_nested != 0) && AIL_API_background() == 0)
    {
        outresint(iFirst);
    }

    AIL_debug_depth = AIL_debug_depth - 1;
    return iFirst;
}

extern "C" void AIL_shutdown()
{
    AIL_debug_depth = AIL_debug_depth + 1;

    if (AIL_debug_enabled != 0 && (AIL_debug_depth == 1 || AIL_debug_nested != 0) && AIL_API_background() == 0)
    {
        AIL_debug_log("@AIL_shutdown()");
    }

    InMilesMutex();

    if (AIL_started != 0)
    {
        AIL_started = 0;
        AIL_API_shutdown();
    }

    AIL_configure_logging(NULL, NULL, LOG_MODE_NONE);
    OutMilesMutex();

    AIL_debug_depth = AIL_debug_depth - 1;
}

static void outresstr(const char* pResult)
{
    if (pResult == NULL)
    {
        AIL_debug_log("!-Result = NULL (no error)");
    }
    else
    {
        AIL_debug_log("!-Result = %s", pResult);
    }
}

