extern "C" int MC_open_output_filter(const char* pName, _DIG_DRIVER* pDriver, int iMatrix)
{
    int iProvider;

    if (iMatrix != 0 && (pDriver->flags & DRIVER_FLAG_16_BITS) == 0)
    {
        AIL_set_error(MATRIX_FILTER_ERROR);
        return 0;
    }

    if (AIL_find_filter(pName, &iProvider) == 0)
    {
        AIL_set_error(OUTPUT_FILTER_ERROR);
        return 0;
    }

    return AIL_open_filter(iProvider, pDriver) != 0;
}
